 21	namespace
 22	{
 23	    const float kPi = 3.14159265358979323846f;
 24	
 25	    const int kCircleSegments = 12;
 26	    const float kCircleCenterDotRadius = 1.5f;
 27	
 28	    const float kJointAnchorRadius = 2.5f;
 29	    const float kJointRestMarkRadius = 1.5f;
 30	    const float kJointLimitTickSize = 4.0f;
 31	    const int kSpringCoilSegments = 8;
 32	    const float kSpringCoilWidth = 4.0f;
 33	
 34	    const float kCenterOfMassRadius = 3.0f;
 35	    const float kSleepIndicatorRadius = 4.0f;
 36	    const int kSleepIndicatorSegments = 8;
 37	
 38	    const float kContactNormalMinLength = 4.0f;
 39	    const float kVelocityScale = 0.1f;
 40	    const float kArrowHeadSize = 4.0f;
 41	    const float kMinDrawLength = 0.5f;
 42	
 43	    const float kSensorAlphaScale = 0.5f;
 44	    const float kRestingIntensity = 0.35f;
 45	    const float kStaticIntensity = 0.6f;
 46	
 47	    const int kDebugDrawLocalZOrder = 1000;
 48	
 49	    void expandBounds(const Vec2& point, Vec2& lower, Vec2& upper, bool& valid)
 50	    {
 51	        if (!valid)
 52	        {
 53	            lower = point;
 54	            upper = point;
 55	            valid = true;
 56	            return;
 57	        }
 58	
 59	        lower.x = std::min(lower.x, point.x);
 60	        lower.y = std::min(lower.y, point.y);
 61	        upper.x = std::max(upper.x, point.x);
 62	        upper.y = std::max(upper.y, point.y);
 63	    }
 64	}
