 66	PhysicsDebugDraw::PhysicsDebugDraw()
 67	: _drawNode(nullptr)
 68	, _initialized(false)
 69	{
 70	    _config.drawShapes = true;
 71	    _config.drawJoints = true;
 72	    _config.drawContacts = false;
 73	    _config.drawBoundingBoxes = false;
 74	    _config.drawCentersOfMass = false;
 75	    _config.drawVelocities = false;
 76	    _config.drawSleepState = false;
 77	    _config.shapeColor = Color4F(0.0f, 1.0f, 0.0f, 0.5f);
 78	    _config.jointColor = Color4F(0.0f, 0.0f, 1.0f, 0.8f);
 79	    _config.contactColor = Color4F(1.0f, 0.0f, 0.0f, 1.0f);
 80	    _config.bbColor = Color4F(1.0f, 1.0f, 0.0f, 0.3f);
 81	    _config.lineWidth = 1.0f;
 82	}
