155	void PhysicsDebugDraw::drawWorld(PhysicsWorld* world)
156	{
157	    if (!_initialized || _drawNode == nullptr || world == nullptr)
158	    {
159	        return;
160	    }
161	
162	    beginDraw();
163	
164	    for (const auto& body : world->getAllBodies())
165	    {
166	        drawBody(body);
167	    }
168	
169	    if (_config.drawJoints)
170	    {
171	        for (auto joint : world->_joints)
172	        {
173	            drawJoint(joint);
174	        }
175	    }
176	
177	    endDraw();
178	}
