180	void PhysicsDebugDraw::drawBody(PhysicsBody* body)
181	{
182	    if (_drawNode == nullptr || body == nullptr)
183	    {
184	        return;
185	    }
186	
187	    const Vector<PhysicsShape*>& shapes = body->getShapes();
188	
189	    if (_config.drawShapes)
190	    {
191	        for (const auto& shape : shapes)
192	        {
193	            drawShape(shape);
194	        }
195	    }
196	
197	    if (_config.drawBoundingBoxes)
198	    {
199	        Vec2 lower;
200	        Vec2 upper;
201	        bool valid = false;
202	
203	        for (const auto& shape : shapes)
204	        {
205	            const PhysicsShape::Type type = shape->getType();
206	            for (auto subShape : shape->_cpShapes)
207	            {
208	                switch (type)
209	                {
210	                    case PhysicsShape::Type::CIRCLE:
211	                    {
212	                        const float radius = PhysicsHelper::cpfloat2float(cpCircleShapeGetRadius(subShape));
213	                        const Vec2 centre = body->local2World(PhysicsHelper::cpv2point(cpCircleShapeGetOffset(subShape)));
214	                        expandBounds(centre - Vec2(radius, radius), lower, upper, valid);
215	                        expandBounds(centre + Vec2(radius, radius), lower, upper, valid);
216	                        break;
217	                    }
218	                    case PhysicsShape::Type::BOX:
219	                    case PhysicsShape::Type::POLYGON:
220	                    {
221	                        const int count = cpPolyShapeGetCount(subShape);
222	                        for (int i = 0; i < count; ++i)
223	                        {
224	                            expandBounds(body->local2World(PhysicsHelper::cpv2point(cpPolyShapeGetVert(subShape, i))),
225	                                         lower, upper, valid);
226	                        }
227	                        break;
228	                    }
229	                    case PhysicsShape::Type::EDGESEGMENT:
230	                    case PhysicsShape::Type::EDGEBOX:
231	                    case PhysicsShape::Type::EDGEPOLYGON:
232	                    case PhysicsShape::Type::EDGECHAIN:
233	                    {
234	                        expandBounds(body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetA(subShape))),
235	                                     lower, upper, valid);
236	                        expandBounds(body->local2World(PhysicsHelper::cpv2point(cpSegmentShapeGetB(subShape))),
237	                                     lower, upper, valid);
238	                        break;
239	                    }
240	                    case PhysicsShape::Type::UNKNOWN:
241	                    default:
242	                        break;
243	                }
244	            }
245	        }
246	
247	        if (valid)
248	        {
249	            drawBoundingBox(Rect(lower.x, lower.y, upper.x - lower.x, upper.y - lower.y), _config.bbColor);
250	        }
251	    }
252	
253	    // the body local origin is its centre of gravity
254	    const Vec2 centerOfMass = body->local2World(Vec2::ZERO);
255	
256	    if (_config.drawCentersOfMass)
257	    {
258	        drawCenterOfMass(centerOfMass, kCenterOfMassRadius, _config.contactColor);
259	    }
260	
261	    if (_config.drawVelocities)
262	    {
263	        drawVelocityVector(centerOfMass, body->getVelocity(), _config.jointColor);
264	    }
265	
266	    if (_config.drawSleepState)
267	    {
268	        drawSleepIndicator(centerOfMass, body->isResting(), _config.bbColor);
269	    }
270	}
