478	void PhysicsDebugDraw::drawContactPoint(const Vec2& point, const Vec2& normal, float depth,
479	                                        const Color4F& color)
480	{
481	    if (_drawNode == nullptr)
482	    {
483	        return;
484	    }
485	
486	    _drawNode->drawDot(point, kJointAnchorRadius, color);
487	
488	    if (normal.isZero())
489	    {
490	        return;
491	    }
492	
493	    const float length = std::max(std::fabs(depth), kContactNormalMinLength);
494	    _drawNode->drawLine(point, point + normal.getNormalized() * length, color);
495	}
496	
497	void PhysicsDebugDraw::drawVelocityVector(const Vec2& pos, const Vec2& vel, const Color4F& color)
498	{
499	    if (_drawNode == nullptr)
500	    {
501	        return;
502	    }
503	
504	    const Vec2 delta = vel * kVelocityScale;
505	    if (delta.getLength() < kMinDrawLength)
506	    {
507	        return;
508	    }
509	
510	    const Vec2 tip = pos + delta;
511	    const Vec2 dir = delta.getNormalized();
512	    const Vec2 back = tip - dir * kArrowHeadSize;
513	    const Vec2 side = dir.getPerp() * (kArrowHeadSize * 0.5f);
514	
515	    _drawNode->drawLine(pos, tip, color);
516	    _drawNode->drawLine(tip, back + side, color);
517	    _drawNode->drawLine(tip, back - side, color);
518	}
519	
520	void PhysicsDebugDraw::drawCenterOfMass(const Vec2& pos, float radius, const Color4F& color)
521	{
522	    if (_drawNode == nullptr)
523	    {
524	        return;
525	    }
526	
527	    const float r = radius > 0.0f ? radius : kCenterOfMassRadius;
528	
529	    _drawNode->drawDot(pos, r, color);
530	    _drawNode->drawLine(pos - Vec2(r * 2.0f, 0.0f), pos + Vec2(r * 2.0f, 0.0f), color);
531	    _drawNode->drawLine(pos - Vec2(0.0f, r * 2.0f), pos + Vec2(0.0f, r * 2.0f), color);
532	}
533	
534	void PhysicsDebugDraw::drawSleepIndicator(const Vec2& pos, bool sleeping, const Color4F& color)
535	{
536	    if (_drawNode == nullptr)
537	    {
538	        return;
539	    }
540	
541	    if (sleeping)
542	    {
543	        _drawNode->drawDot(pos, kSleepIndicatorRadius, color);
544	    }
545	    else
546	    {
547	        _drawNode->drawCircle(pos, kSleepIndicatorRadius, 0.0f, kSleepIndicatorSegments, false, color);
548	    }
549	}
