629	Color4F PhysicsDebugDraw::getShapeColor(PhysicsShape* shape) const
630	{
631	    if (shape == nullptr)
632	    {
633	        return _config.shapeColor;
634	    }
635	
636	    if (shape->isSensor())
637	    {
638	        const Color4F& base = _config.shapeColor;
639	        return Color4F(base.r, base.g, base.b, base.a * kSensorAlphaScale);
640	    }
641	
642	    return getBodyColor(shape->getBody());
643	}
