  3	static void DrawCircle(cpVect p, cpFloat /*a*/, cpFloat r, cpSpaceDebugColor outline, cpSpaceDebugColor fill, cpDataPointer data)
  4	{
  5	    const Color4F fillColor(fill.r, fill.g, fill.b, fill.a);
  6	    const Color4F outlineColor(outline.r, outline.g, outline.b, outline.a);
  7	    DrawNode* drawNode = static_cast<DrawNode*>(data);
  8	    float radius = PhysicsHelper::cpfloat2float(r);
  9	    Vec2 centre = PhysicsHelper::cpv2point(p);
 10	    
 11	    static const int CIRCLE_SEG_NUM = 12;
 12	    Vec2 seg[CIRCLE_SEG_NUM] = {};
 13	    
 14	    for (int i = 0; i < CIRCLE_SEG_NUM; ++i)
 15	    {
 16	        float angle = (float)i * M_PI / (float)CIRCLE_SEG_NUM * 2.0f;
 17	        Vec2 d(radius * cosf(angle), radius * sinf(angle));
 18	        seg[i] = centre + d;
 19	    }
 20	    drawNode->drawPolygon(seg, CIRCLE_SEG_NUM, fillColor, 1, outlineColor);
 21	}
