 59	static cpSpaceDebugColor ColorForShape(cpShape *shape, cpDataPointer /*data*/)
 60	{
 61	    if(cpShapeGetSensor(shape)){
 62	        return LAColor(1.0f, 0.3f);
 63	    } else {
 64	        cpBody *body = cpShapeGetBody(shape);
 65	        
 66	        if(cpBodyIsSleeping(body)){
 67	            return LAColor(0.2f, 0.3f);
 68	        } else if(body->sleeping.idleTime > shape->space->sleepTimeThreshold) {
 69	            return LAColor(0.66f, 0.3f);
 70	        } else {
 71	            
 72	            float intensity = (cpBodyGetType(body) == CP_BODY_TYPE_STATIC ? 0.15f : 0.75f);
 73	            return RGBAColor(intensity, 0.0f, 0.0f, 0.3f);
 74	        }
 75	    }
 76	}
